        public static DataTable GetDataByDoID(Nullable<int> companyID, Nullable<int> periodID, string DeliveryOrderID, string type, SqlConnection objConnection = null, SqlTransaction objTransaction = null)
        {
            DataTable dt = null;
            StringBuilder sb = new StringBuilder();

            const string Query = @" 
SELECT * FROM SAL_GateIn 
INNER JOIN SET_DocumentType ON SET_DocumentType.DocumentTypeID = SAL_GateIn.DocumentTypeID
AND SET_DocumentType.CompanyID = SAL_GateIn.CompanyID
AND SET_DocumentType.PeriodID = SAL_GateIn.PeriodID
WHERE SAL_GateIn .CompanyID = @CompanyID and DeliveryOrderID = @DeliveryOrderID
";

            if (type != "")
            {
                sb.Append(" AND SET_DocumentType.DocumentType like '%" + type + "%' ");
            }

            try
            {
                SqlParameter[] sqlparams = new SqlParameter[3];
                sqlparams[0] = new SqlParameter("@CompanyID", companyID);
                sqlparams[1] = new SqlParameter("@PeriodID", periodID);
                sqlparams[2] = new SqlParameter("@DeliveryOrderID", DeliveryOrderID);

                DataSet ds = null;

                if (objTransaction != null)
                    ds = SqlHelper.ExecuteDataset(objTransaction, CommandType.Text, Query + sb.ToString(), sqlparams);
                else if (objConnection != null)
                    ds = SqlHelper.ExecuteDataset(objConnection, CommandType.Text, Query + sb.ToString(), sqlparams);
                else
                    ds = SqlHelper.ExecuteDataset(CommandType.Text, Query + sb.ToString(), sqlparams);

                if (ds != null && ds.Tables != null && ds.Tables.Count > 0)
                    dt = ds.Tables[0];
            }
            catch (Exception ex)
